# AIC interpreter (minimal) for this task
class AIC:
    def __init__(self):
        self.env = {}
        self.heap = {}
        self.next_ptr = 1
        self.out = []

    def alloc(self, n):
        p = self.next_ptr
        self.next_ptr += 1
        self.heap[p] = bytearray(n + 1)
        return p

    def getbuf(self, p):
        return self.heap[p]

    def eval(self, expr):
        if isinstance(expr, int):
            return expr
        if isinstance(expr, str):
            return expr
        op = expr[0]
        args = expr[1:]

        if op == '!':
            name, val = args[0], self.eval(args[1])
            self.env[name] = val
            return val
        if op == '^':
            return self.eval(args[0])
        if op == 'D':
            r = None
            for s in args:
                r = self.eval(s)
            return r
        if op == 'H':
            return self.alloc(self.eval(args[0]))
        if op == '@':
            buf = self.env[args[0]] if isinstance(args[0], str) and args[0] in self.env else self.eval(args[0])
            idx = self.eval(args[1])
            return self.getbuf(buf)[idx]
        if op == '@!':
            buf = self.env[args[0]] if isinstance(args[0], str) and args[0] in self.env else self.eval(args[0])
            idx = self.eval(args[1])
            val = self.eval(args[2])
            self.getbuf(buf)[idx] = val & 0xFF
            return val
        if op == 'N':
            return str(self.eval(args[0]))
        if op == '.':
            parts = []
            for a in args:
                parts.append(str(self.eval(a)))
            self.out.append(' '.join(parts))
            return 0
        if op in ('+', '-', '*', '/', '%', '==', '!=', '<', '>', '<=', '>=', '&', '|', '^^', '<<', '>>', '&&', '||'):
            a = self.eval(args[0]); b = self.eval(args[1])
            if op == '+': return a + b
            if op == '-': return a - b
            if op == '*': return a * b
            if op == '/': return a // b
            if op == '%': return a % b
            if op == '==': return int(a == b)
            if op == '!=': return int(a != b)
            if op == '<': return int(a < b)
            if op == '>': return int(a > b)
            if op == '<=': return int(a <= b)
            if op == '>=': return int(a >= b)
            if op == '&': return a & b
            if op == '|': return a | b
            if op == '^^': return a ^ b
            if op == '<<': return a << b
            if op == '>>': return a >> b
            if op == '&&': return int(bool(a) and bool(b))
            if op == '||': return int(bool(a) or bool(b))
        if op == '~':
            return ~self.eval(args[0])
        if op == '?':
            return self.eval(args[1]) if self.eval(args[0]) else self.eval(args[2])
        raise Exception(f"Unknown op: {op}")

    def run(self, program):
        for stmt in program:
            self.eval(stmt)
        return '\n'.join(self.out)


