typedef struct {
    long long *data;
    long long len;
    long long cap;
} Vec;

Vec *vec_new(long long cap) {
    Vec *v = (Vec *)malloc(sizeof(Vec));
    v->data = (long long *)malloc(sizeof(long long) * (cap > 0 ? cap : 1));
    v->len = 0;
    v->cap = cap > 0 ? cap : 1;
    return v;
}

void vec_push(Vec *v, long long x) {
    if (v->len == v->cap) {
        v->cap *= 2;
        v->data = (long long *)realloc(v->data, sizeof(long long) * v->cap);
    }
    v->data[v->len++] = x;
}

long long vec_len(Vec *v) {
    return v->len;
}

long long vec_get(Vec *v, long long i) {
    return v->data[i];
}

int main(void) {
    Vec *v = vec_new(2);
    vec_push(v, 10);
    vec_push(v, 20);
    vec_push(v, 30);

    printf("%lld %lld\n", vec_len(v), vec_get(v, 0));

    free(v->data);
    free(v);
