/* Minimal JSON object representation for this task:
   - build an object with key "count" -> 12
   - serialize it
   - parse it back
   - print the value of count
*/

typedef struct {
    char *key;
    int value;
} Pair;

typedef struct {
    Pair *pairs;
    int count;
} JObj;

static JObj *json_obj_new(void) {
    JObj *o = (JObj *)malloc(sizeof(JObj));
    o->pairs = NULL;
    o->count = 0;
    return o;
}

static void json_obj_set_int(JObj *o, const char *key, int value) {
    o->pairs = (Pair *)realloc(o->pairs, sizeof(Pair) * (o->count + 1));
    o->pairs[o->count].key = strdup(key);
    o->pairs[o->count].value = value;
    o->count++;
}

static char *json_stringify(JObj *o) {
    size_t cap = 64;
    char *buf = (char *)malloc(cap);
    size_t len = 0;
    buf[len++] = '{';
    for (int i = 0; i < o->count; i++) {
        if (i > 0) buf[len++] = ',';
        buf[len++] = '"';
        const char *k = o->pairs[i].key;
        for (size_t j = 0; k[j]; j++) buf[len++] = k[j];
        buf[len++] = '"';
        buf[len++] = ':';
        char num[32];
        snprintf(num, sizeof(num), "%d", o->pairs[i].value);
        for (size_t j = 0; num[j]; j++) buf[len++] = num[j];
    }
    buf[len++] = '}';
    buf[len] = '\0';
    return buf;
}

static int json_parse_get_int(const char *s, const char *key) {
    /* simplistic parser: find "key": <int> */
    char pattern[64];
    snprintf(pattern, sizeof(pattern), "\"%s\":", key);
    const char *p = strstr(s, pattern);
    if (!p) return 0;
    p += strlen(pattern);
    while (*p == ' ') p++;
    return atoi(p);
}

int main(void) {
    JObj *obj = json_obj_new();
    json_obj_set_int(obj, "count", 12);

    char *serialized = json_stringify(obj);

    int parsed = json_parse_get_int(serialized, "count");

    printf("%d\n", parsed);

    free(serialized);
    for (int i = 0; i < obj->count; i++) free(obj->pairs[i].key);
    free(obj->pairs);
    free(obj);
    return 0;
}

